import pandas as pd

def clean(df):
    df = df.copy()
    # strip whitespace from object columns
    obj_cols = df.select_dtypes(include='object').columns
    for col in obj_cols:
        df[col] = df[col].astype(str).str.strip()
    # standardise island label variants
    island_map = {
        'Torgerson': 'Torgersen',
        'Bisco': 'Biscoe'
    }
    df['island'] = df['island'].replace(island_map)
    # standardise sex label variants
    if 'sex' in df.columns:
        df['sex'] = df['sex'].str.lower()
    # parse body_mass_g which is text with commas / numbers written as text
    if 'body_mass_g' in df.columns and df['body_mass_g'].dtype == object:
        df['body_mass_g'] = df['body_mass_g'].str.replace(',', '', regex=False)
        df['body_mass_g'] = pd.to_numeric(df['body_mass_g'], errors='coerce')
    # ensure numeric columns are numeric
    for col in ['bill_length_mm', 'bill_depth_mm', 'flipper_length_mm', 'year']:
        if col in df.columns and df[col].dtype == object:
            df[col] = pd.to_numeric(df[col], errors='coerce')
    # remove exact duplicate rows and duplicate penguin_id
    df = df.drop_duplicates()
    if 'penguin_id' in df.columns:
        df = df.drop_duplicates(subset=['penguin_id'], keep='first')
    return df

def answer(df):
    df_c = clean(df)
    # count penguins per island after cleaning
    df_c = df_c.dropna(subset=['island'])
    counts = df_c.groupby('island').size()
    return {str(k): int(v) for k, v in counts.items()}
